/* Les fiches des personnages : qui ils sont, ce qu'ils savent, ce qu'ils pensent, comment ils parlent.
   Le moteur de la parole s'en sert quand aucune réplique écrite d'avance ne convient. */
(function (G) {
  'use strict';
  var CH = G.CHAPTERS || {}, L = CH.londres, PR = CH.prologue || G.SCENE;
  function day(api) { return Math.floor(api.s.min / 1440); }
  function cls(f) { return f.fr ? 'fr' : /police/.test(f.groupe) ? 'o' : /savant|diplomate|mondain|occultiste|hotel|domestique/.test(f.groupe) ? 'h' : 'p'; }
  function brule(api) { return api.s.min >= 2820; }

  // ================================================================ Londres
  if (L) {
    L.fiches = {
      smith: { groupe: 'savant', reg: 'savant', tics: ['Mon cher,', 'Voyez-vous,', 'Hum.'],
        dada: ['Houdini me l’a dit cent fois : regardez toujours les mains.', 'Il faudra que je vous montre ma collection d’ectoplasmes en mousseline. Quarante-trois faux, tous démasqués.'],
        moi: { nom: '« Julius Arthur Smith. Vous le savez bien, voyons. »', age: '« Soixante-quatre ans, et l’impression d’en avoir mille ce soir. »', origine: '« Né à Whitby, au bord de la mer du Nord. Une ville de brumes et de vieilles légendes. Ça m’a donné le goût des fantômes, et celui de les démonter. »', domicile: '« À St John’s Wood, toujours. Vous y avez dîné vingt fois. »', famille: '« Jamais marié. La science est une épouse jalouse, et Beddows une gouvernante tyrannique. »', metier: '« Professeur, chasseur de médiums, et depuis ce soir, prophète malgré moi. »', loisirs: '« Les échecs par correspondance avec un vieux jésuite de Louvain. Il gagne toujours. »', peur: '« Peur ? » Il tire sur sa pipe. « Pour la première fois de ma vie, oui. Ne le répétez pas. »', croit: '« Je ne croyais à rien. Je crois désormais qu’il y a des choses qui reviennent. Ce n’est pas la même chose que croire aux fantômes. »', humeur: '« Épuisé, exalté. Comme après chaque conférence. Et inquiet, un peu. »', guerre: '« Trop vieux pour le front. J’ai perdu un neveu à Loos. Il venait me raconter ses rêves. »', boire: '« Un sherry, volontiers. Beddows le verse trop court, comme toujours. »', secret: '« Un secret ? » Il hésite. « Un antiquaire m’a écrit, la semaine dernière. Je n’ai pas répondu. J’aurais peut-être dû. »', joueur: '« Vous êtes l’une des rares personnes à qui je fais confiance, {m}. Ne me décevez pas. »', argent: '« Assez pour mes livres, pas assez pour mes ambitions. »', defaut: ['« Voilà une question bien personnelle, {m}. »'] },
        sait: { MOUSTACHU: '« Un homme brun qui vous regardait ? Ici, tout le monde regarde tout le monde, mon cher. Si vous le revoyez, montrez-le-moi. » Mais ses doigts se sont crispés sur sa pipe.', PROJECTEUR: '« Mes plaques ? Trois ans de photographies, prises chez des témoins de toute l’Europe. Je les garde chez moi, à St John’s Wood. Vous les verrez, si vous êtes sage. »', BEDDOWS: '« Beddows ? Trente et un ans à mon service. Il connaît mes manies mieux que moi. Ce soir, je le trouve nerveux. »', HANTISE: '« Les hantises sont des tentatives de retour, j’en suis convaincu. Quelque chose cherche à revenir, et se trompe de porte. »', FANTOME: '« Les fantômes que j’ai démasqués étaient de la mousseline et du phosphore. Ceux dont je parle ce soir ne sont pas faits de mousseline. »', MUSEE: '« Le British Museum ? J’y ai ma place réservée sous la coupole depuis 1890. »', STJOHN: '« Ma maison. Mes livres. Je ne serai tranquille que quand je serai rentré. »', OCCULTE: '« L’occultisme est une maladie de l’âme. Mais certaines maladies ont des causes réelles. »', TURCS: '« Les Turcs ? Pourquoi me parlez-vous des Turcs ? » Un silence trop long. « Pour rien. »', MAKRYAT: '« Makryat… » Il pâlit légèrement. « Un antiquaire. Il m’a écrit. Je vous en parlerai plus tard, pas ici. »', TRAIN: '« Les trains me rendent mélancolique. Ils vont toujours quelque part. »', INSTITUT: '« L’Institut impérial, sa coupole, ses mécènes qui s’endorment. Je les aime bien, au fond. »' },
        avis: { spiritisme: '« Doyle est un ami, et un homme admirable. Il se trompe sur tout, avec une sincérité qui me brise le cœur. »', egypte: '« Toutankhamon ? Carter m’a écrit. Il dit qu’on entend respirer, la nuit, dans l’antichambre. Il plaisante, j’espère. »' },
        relances: [{ q: '« Et vous, {m}, vous m’avez trouvé ridicule, ce soir ? »', oui: '« Merci de votre franchise. Moi aussi, un peu. »', non: '« Vous êtes gentil. Ou poli. Les deux me vont. »' }, { q: '« Vous resterez à Londres quelques jours, j’espère ? »', oui: '« Bien. J’aurai peut-être besoin de vous. »', non: '« Dommage. J’aurais aimé… Enfin. »' }] },

      beddows: { groupe: 'domestique', reg: 'domestique', tics: ['Pardon, {m},', 'Si je puis me permettre,'],
        dada: ['Monsieur ne mange presque plus.', 'J’ai repassé ses chemises ce matin. Il ne les met plus.'],
        moi: { nom: '« James Beddows, {m}. Au service du professeur. »', age: '« Cinquante-huit ans, {m}. »', origine: '« De Preston, dans le Lancashire. Mon père était filateur. »', famille: '« Une sœur, à Margate. Elle tient une pension. Je ne l’ai pas vue depuis la guerre. »', metier: '« Valet, majordome, secrétaire. Tout ce que Monsieur a besoin que je sois, depuis trente et un ans. »', loisirs: function (api) { return brule(api) ? '« Les pigeons, {m}. J’en avais, à St John’s Wood. » Sa voix se brise. « J’en avais. »' : '« Les pigeons, {m}. J’ai un pigeonnier au fond du jardin de Monsieur. Onze voyageurs. Ils reviennent toujours, eux. »'; }, peur: function (api) { return api.flag('cheapsideVu') ? '« Peur ? » Il regarde vers le lit. « Je n’ai plus que ça, {m}. »' : '« De rien, {m}. Enfin… de rien de précis. »'; }, croit: '« Je suis méthodiste, {m}. Je croyais savoir ce qu’il y avait après. Je ne sais plus. »', humeur: function (api) { return api.flag('cheapsideVu') ? '« Je ne dors plus, {m}. Personne ne dort, ici. »' : '« Bien, {m}, merci. »'; }, guerre: '« Trop vieux, {m}. J’ai servi le thé aux blessés de l’hôpital de Marylebone. »', secret: function (api) { return api.flag('cheapsideVu') ? 'Il ouvre la bouche, la referme. Ses yeux vont vers le lit. « Pas ici, {m}. Jamais ici. »' : '« Je n’ai pas de secrets, {m}. Seulement ceux de Monsieur, et ils ne sont pas à moi. »'; }, joueur: '« Vous êtes un ami de Monsieur. C’est assez pour moi. »', defaut: ['« Je ne suis pas sûr que ce soit ma place de répondre, {m}. »'] },
        sait: { MOUSTACHU: '« Je n’ai d’yeux que pour Monsieur, ce soir, {m}. Je n’ai pas remarqué ce monsieur. » Il jette pourtant un regard inquiet vers la salle.', PROJECTEUR: '« Les plaques de Monsieur ? Je les ai portées moi-même, {m}. Monsieur ne laisse personne d’autre y toucher. »', SMITH: function (api) { return api.flag('cheapsideVu') ? '« Monsieur… » Il ne finit pas sa phrase. « Monsieur est très malade. »' : '« Monsieur est un grand homme, {m}. Et un homme fatigué. »'; }, FLEMING: '« La police ? Monsieur ne veut pas de la police. Il a été très clair. »', STJOHN: function (api) { return brule(api) ? '« La maison… » Ses mains tremblent. « Je ne veux pas en parler, {m}. »' : '« La maison de Monsieur. Je la tiens propre depuis trente ans. »'; }, MUSEE: '« Monsieur y passe ses journées. Moi, j’attends dehors, sur le banc des cochers. »', CHEAPSIDE: '« Ce n’est pas un endroit pour Monsieur. Mais il a voulu venir ici. Il a insisté. »', TURCS: '« Je n’aime pas qu’on me parle des Turcs, {m}. Pas en ce moment. »', ARGENT: '« Monsieur a fait retirer de l’argent. Beaucoup. Ce n’est pas mes affaires. »' },
        relances: [{ q: '« Vous allez l’aider, n’est-ce pas, {m} ? Vous allez faire ce qu’il demande ? »', oui: '« Merci. » Ses épaules s’affaissent. « Merci. »', non: '« Alors… alors je ne sais pas ce qui va se passer. »' }] },

      fleming: { groupe: 'police', reg: 'sec', mefiant: 0.8, tics: ['Écoutez,', 'Bon.'],
        dada: ['J’ai quarante dossiers ouverts et un seul inspecteur. Moi.', 'Il faut que je finisse ce rapport avant six heures. Il ne se finira pas.'],
        moi: { nom: '« Fleming. Inspecteur. C’est écrit sur la porte. »', age: '« Quarante-six ans. J’en parais soixante, d’après ma femme. »', origine: '« Bermondsey. Les docks. On n’en sort pas, on s’en éloigne. »', domicile: '« Lewisham. Ça ne vous regarde pas, mais voilà. »', famille: '« Une femme, Margaret. Deux filles, qui trouvent que je ne rentre jamais. Elles ont raison. »', metier: '« Vingt-deux ans de police. On voit tout, à la longue. Puis on voit trop. »', loisirs: '« Un jardin ouvrier, à Lewisham. Des poireaux. Les poireaux ne mentent pas. »', peur: '« De quoi j’ai peur ? Des choses qui n’ont pas d’explication. Elles finissent toujours sur mon bureau. »', croit: '« Je ne crois pas aux fantômes. Je crois aux gens qui ont intérêt à ce qu’on y croie. »', humeur: '« Fatigué. Comme d’habitude. »', guerre: '« Sergent, à Ypres. Trois ans. Ensuite on m’a rendu mon uniforme bleu. »', boire: '« Pas en service. »', argent: '« Un salaire d’inspecteur. Ça paie les poireaux. »', secret: '« J’en ai plein. Ils s’appellent des dossiers. »', joueur: '« Je n’ai pas d’opinion sur vous. Pas encore. Ça viendra. »', defaut: ['« Je ne vois pas le rapport avec l’enquête. »'] },
        sait: { SMITH: '« Le professeur Smith ? Il nous a aidés sur l’affaire des médiums de Kensington, en dix-neuf. Un homme sérieux. Pour un chasseur de fantômes. »', RIGBY: '« Rigby ? Bon sergent. Trop de fumée dans les poumons, trop d’années dans les incendies. Il voit des incendiaires partout. Il a souvent raison. »', MUSTAPHA: '« L’attaché turc ? Courtois. Bien élevé. Il ment avec beaucoup de grâce. »', BUTTER: '« Butter ? Un vieux fou des trains, à Camberwell. Inoffensif. »', ATKINS: '« La logeuse de Stoke Newington ? Elle fait payer six pence pour voir la chambre. Je n’ai pas de loi contre ça. Je devrais. »', CHELSEA: '« Le Chelsea Arms ? Un hôtel où l’on ne pose pas de questions. On a eu tort de ne pas en poser. »', ISLINGTON: '« Islington. Des antiquaires, des receleurs, et ceux qui sont les deux. »', STOKE: '« Stoke Newington. Des petites gens, des petites maisons. Et un homme qui part en fumée. »', MUSEE: '« Le British Museum ? Ils ont des gardiens. Mieux payés que mes agents. »', ARME: '« Mes hommes n’ont pas d’arme à feu. Ici, c’est l’Angleterre. On compte sur le bon sens et la matraque. »', POLICE: '« La police fait ce qu’elle peut avec ce qu’elle a. Ce qu’elle a, c’est moi. »', BEDDOWS: '« Le domestique de Smith ? On le cherche. On cherche beaucoup de monde, cette semaine. »', OCCULTE: '« L’occultisme ? Laissez ça aux journaux du dimanche. »', FANTOME: '« Les fantômes ne laissent pas d’empreintes. Les assassins, si. »' },
        avis: { spiritisme: '« Les médiums ? Des escrocs, et les pires : ils volent les veuves. »', turquie: '« La politique turque ne m’intéresse que quand elle meurt à Chelsea. »' },
        relances: [{ q: '« Et vous, qu’est-ce que vous faites dans cette histoire, exactement ? »', oui: '« Ce n’était pas une question à laquelle on répond par oui. »', non: '« C’est bien ce qui m’inquiète. »', autre: '« Hm. Je note. »' }, { q: '« Vous ne me cachez rien, j’espère ? »', oui: '« Alors dites-le. Maintenant. »', non: '« Bien. Je vous croirai jusqu’à preuve du contraire. »' }] },

      rigby: { groupe: 'police', reg: 'populaire', tics: ['Ah,', 'Voyez-vous,'],
        dada: ['Un incendie, ça se lit comme un livre, si on sait lire les cendres.', 'J’en ai vu brûler, des maisons. Pas une ne brûle comme une autre.'],
        moi: { nom: '« Sergent Rigby, brigade des incendies. Pour vous servir. »', age: '« Cinquante et un ans. Vingt-cinq dans la fumée. »', origine: '« Glasgow, à l’origine. Ça s’entend encore, quand je me fâche. »', famille: '« Une femme et un chien. Le chien m’écoute davantage. »', metier: '« Je regarde ce qui reste quand tout a brûlé, et je dis pourquoi c’est parti. »', loisirs: '« Le football. Je suis pour les Rangers, ici personne ne comprend. »', peur: '« Les caves. Le feu qui couve sous les planchers. On le croit mort, il vous attend. »', croit: '« Je crois aux allumettes et à l’essence. Le reste, c’est pour les curés. »', humeur: '« Je tousse, mais je tiens debout. »', guerre: '« Sapeur, sur la Somme. On faisait sauter des choses. Ça m’est resté. »', boire: '« Un whisky, après le service. Un vrai, de chez nous. »', defaut: ['« Ça, c’est pas mes oignons, {m}. »'] },
        sait: { FLEMING: '« L’inspecteur Fleming ? Un bon. Il dort pas assez. »', STJOHN: function (api) { return brule(api) ? '« St John’s Wood ? Le feu est parti du bureau, à l’essence. Celui qui a fait ça savait ce qu’il voulait détruire. »' : '« St John’s Wood ? Un quartier de messieurs. Rien n’y brûle jamais. »'; }, SMITH: '« Le professeur ? Introuvable. Ni vivant ni mort. Les cendres ne mentent pas : il n’était pas dans la maison. »', BEDDOWS: '« Le domestique ? Il a filé avant le feu, ou pendant. Je donnerais cher pour lui parler. »', YARD: '« Le Yard, c’est ma maison. Une maison qui sent le papier mouillé et le thé froid. »', POLICE: '« La police ? Une grande famille. Avec ses ivrognes, comme toutes les familles. »', MEURTRES: function (api) { return day(api) >= 3 ? '« Les Turcs de Chelsea ? C’est pour Fleming, ça. Moi, je m’occupe de ce qui brûle. »' : null; }, TEMOIN: '« Les témoins ? Ils ont tous vu quelque chose de différent. C’est normal, la nuit, avec un feu. »' },
        relances: [{ q: '« Vous fumez, {m} ? Faites attention à vos allumettes, dans ces hôtels. »', oui: '« Alors méfiez-vous. Un mégot, et c’est la moitié d’un étage. »', non: '« Bien. Une habitude de moins à perdre. »' }] },

      chelseaclerk: { groupe: 'peuple', reg: 'populaire', mefiant: 0.4, tics: ['Écoutez,', 'Bon,'],
        dada: ['Depuis l’affaire, on a deux chambres libres sur trois. Personne veut dormir au troisième.', 'Le patron dit que les journaux, c’est de la publicité. Le patron dort à Brighton.'],
        moi: { nom: '« Tilbury. Albert Tilbury. Personne m’appelle par mon nom, ici. »', age: '« Trente-quatre ans. »', origine: '« Né à Battersea, de l’autre côté du fleuve. »', famille: '« Une fiancée, Doris. Elle veut que je change de place depuis l’histoire des Turcs. »', metier: '« Je donne les clés, je reprends les clés, et je regarde rien. C’est ça, le métier. »', loisirs: '« Les courses de lévriers, à White City. Je perds, mais avec méthode. »', peur: '« Du troisième étage. Depuis la semaine dernière. »', croit: '« Je crois au loyer payé d’avance. »', humeur: '« Je dors mal, si vous voulez savoir. »', guerre: '« Réformé. Les pieds plats. Ils ont sauvé ma vie, mes pieds. »', defaut: ['« Ça regarde que moi, ça. »'] },
        sait: { POLICE: '« La police est passée trois fois. Ils ont mis des scellés, ils ont pris des notes, et un agent dort dans l’escalier. »', TURCS: '« Les Turcs ? Polis, bien mis. Ils se parlaient pas. C’était ça le plus bizarre. »', CHELSEA: '« Le Chelsea Arms, c’est pas le Savoy. Mais c’était un hôtel tranquille, avant. »', ETAGE: '« Le troisième ? N’y montez pas. Y a rien à voir. Enfin… y a trois taches. »', FLEMING: '« L’inspecteur ? Il a des yeux qui vous comptent les dents. »', REGISTRE: '« Le registre, c’est pour la police. Ou pour ceux qui ont de bonnes raisons. »' } },

      mustapha: { groupe: 'diplomate', reg: 'formel', mefiant: 0.6, tics: ['Voyez-vous,', 'Permettez-moi :', 'Je vous en prie :'],
        dada: ['Mon gouvernement attache le plus grand prix à ses relations avec la Couronne. Je le répète beaucoup, ces jours-ci.', 'À Lausanne, nos délégués se battent pour chaque virgule. Ici, je me bats pour chaque visa.'],
        moi: { nom: '« Mustapha Köprülü, attaché auprès de la représentation de la Grande Assemblée nationale de Turquie. Le titre est plus long que le bureau. »', age: '« Trente et un ans. »', origine: '« Né à Constantinople, dans une maison de bois sur le Bosphore. Elle a brûlé en 1912. Tout brûle, chez nous aussi. »', famille: '« Ma mère vit encore à Constantinople. Mon père était au service du Sultan. Nous ne parlons plus de lui. »', metier: '« Diplomate. C’est-à-dire celui qui sourit pendant que les autres signent. »', loisirs: '« Le polo, quand Hurlingham veut bien de moi. Et la poésie persane, en cachette. »', peur: '« Que mon pays soit dépecé une seconde fois. »', croit: '« Je suis musulman, discrètement. À Londres, la discrétion est la meilleure des prières. »', humeur: '« Fort bien, je vous remercie. Un peu de brouillard dans les poumons, comme tout le monde. »', guerre: '« J’étais à Gallipoli. Sous-lieutenant. Nous avons vu vos soldats mourir, et vous les nôtres. Je ne garde de haine contre personne. »', boire: '« Un café, s’il vous plaît. Le thé anglais est une punition. »', secret: '« Un diplomate qui avoue un secret n’est plus diplomate. »', joueur: '« Vous m’êtes sympathique, {m}. Ce qui ne veut pas dire que je vous dirai tout. »', defaut: ['« Permettez-moi de ne pas répondre. »'] },
        sait: { FLEMING: '« L’inspecteur Fleming est venu deux fois. Un homme honnête, et donc dangereux pour un diplomate. »', SMITH: '« Le professeur Smith ? Son nom a circulé à l’ambassade, oui. Je ne puis vous dire pourquoi. »', AMBASSADE: '« La représentation est modeste. Nous attendons qu’on nous reconnaisse officiellement. Lausanne décidera. »', ISLINGTON: '« Islington ? Un quartier où vivent quelques compatriotes. Des marchands, surtout. »', CHELSEA: '« Le Chelsea Arms ? Je n’y suis jamais entré, et après ce qui s’est passé, je ne compte pas commencer. »', TURCS: '« Mes compatriotes de Londres sont peu nombreux et très discrets. C’est pourquoi trois morts d’un coup font tant de bruit. »', POLICE: '« La police anglaise est remarquable. Elle me fait penser à une horloge : précise, et toujours un peu en retard. »' },
        avis: { turquie: '« La Turquie nouvelle naît à Angora, pas à Constantinople. Mustafa Kemal a sauvé ce qui pouvait l’être. »', roi: '« Le roi George est un souverain respecté. Nous en avons eu un aussi. Il est parti en exil sur un navire anglais, en novembre. »', guerre: '« Gallipoli. Je ne vous dirai rien d’autre que ce nom. »' },
        relances: [{ q: '« Vous connaissez Constantinople, {m} ? »', oui: '« Alors vous savez que c’est la plus belle ville du monde, et la plus triste. »', non: '« Allez-y un jour. Prenez l’Orient-Express, si vous avez les moyens. »' }, { q: '« Puis-je vous demander quel est votre intérêt dans cette affaire, {m} ? »', oui: '« Voilà qui ne répond pas à ma question. »', non: '« Je vois. Nous gardons chacun nos secrets. »', autre: '« Je vois. Nous gardons chacun nos secrets. »' }] },

      voisin: { groupe: 'commerce', reg: 'populaire', mefiant: 0.5, tics: ['Ouais,', 'Écoutez voir,'],
        dada: ['Vous voulez des cigarettes, sinon ? J’ai des Gold Flake.', 'Le commerce va mal. Les gens fument moins depuis qu’ils ont plus de sous.'],
        moi: { nom: '« Pruett. Le buraliste. Tout le monde dit « le buraliste », alors… »', age: '« Soixante ans aux prochaines cerises. »', origine: '« Islington, de père en fils. Mon grand-père vendait déjà du tabac à priser dans cette rue. »', famille: '« Une femme, qui tient la caisse mieux que moi. Pas d’enfants. »', metier: '« Tabac, journaux, allumettes. Et les ragots, gratuits. »', loisirs: '« Les pigeons. Et les ragots. »', peur: '« De la boutique d’à côté, si vous voulez la vérité. Les nuits, j’entends des choses. »', croit: '« Je crois à ce que je vois, et j’en vois assez. »', humeur: '« Ça va, ça vient. »', guerre: '« Trop vieux. Mon neveu y est resté. »', boire: '« Une petite bière, le soir, au Crown. »', defaut: ['« Ça vous regarde pas, ça. »'] },
        sait: { ISLINGTON: '« Islington, c’est plus ce que c’était. Avant, on se connaissait tous. Maintenant, y a des étrangers, des antiquaires, des gens qui sortent la nuit. »', POLICE: '« Les flics ? Ils sont passés, ils ont rien vu, ils sont repartis. Comme d’habitude. »', TURCS: '« Des Turcs, y en avait qui venaient voir le vieux. En silence. Ils achetaient rien. »', FLEMING: '« Un inspecteur ? Il a acheté des allumettes et il est reparti. »', ARGENT: '« Les sous, c’est le nerf de la guerre, {m}. »' } },

      atkins: { groupe: 'peuple', reg: 'populaire', tics: ['Oh, mon Dieu,', 'Remarquez,', 'Je vous le dis comme je le pense,'],
        dada: ['Mon pauvre Albert disait toujours que le gaz finirait par nous tuer tous.', 'Vous voulez du thé ? Il est frais d’hier.', 'Six pence la visite, c’est pas cher, pour une chambre pareille. Albert en aurait demandé un shilling.'],
        moi: { nom: '« Mrs Atkins. Constance. Mais Mrs Atkins pour les locataires. »', age: '« Une dame ne dit pas son âge. Disons que j’ai connu la vieille reine. »', origine: '« Née à Hackney, mariée à Stoke Newington. Je suis pas allée bien loin, hein ? »', famille: '« Veuve. Mon Albert est parti avec la grippe espagnole, en dix-neuf. Il a survécu à la guerre pour mourir d’un rhume. »', metier: '« Je tiens la maison. Trois locataires. Enfin, deux, maintenant. »', loisirs: '« Les feuilletons du Daily Mirror. Et les séances, chez Mrs Pembroke, le jeudi. Elle fait parler mon Albert. Il n’a pas changé. »', peur: '« De la chambre de M. Stanley, la nuit. J’ai mis un chiffon sous la porte. Ça sent encore la fumée. »', croit: '« Aux esprits ? Oh oui. Mon Albert me parle, le jeudi. »', humeur: '« Je tiens le coup, mon petit. Faut bien. »', guerre: '« Albert y était. Il en parlait jamais. Il criait, la nuit, voilà tout. »', boire: '« Un petit porto, le dimanche. Pour la circulation. »', argent: '« Les loyers rentrent mal. Alors, la visite à six pence, ça dépanne. »', joueur: '« Vous avez une bonne tête, vous. Une tête de quelqu’un qui paie son loyer. »', defaut: ['« Oh, ça, c’est personnel. »'] },
        sait: { STANLEY: '« M. Stanley ? Un si gentil garçon. Il payait à l’heure. Il ne parlait que de ses trains, mais il payait à l’heure. »', POLICE: '« Le sergent est venu. Il a reniflé la chambre et il a dit « drôle d’affaire ». Ça, j’aurais pu le dire toute seule. »', STOKE: '« Stoke Newington, c’est un quartier respectable. Enfin, c’était. »', BUTTER: '« M. Butter ? Le vieux monsieur des trains ? Il venait voir M. Stanley. Ils parlaient de locomotives pendant des heures. »', TRAIN: '« Les trains, les trains… M. Stanley en avait partout. Des gravures, des maquettes. Il disait que les trains, c’est la seule chose qui va quelque part. »', SUIE: '« La suie ? Au plafond. J’ai frotté trois fois. Elle revient. »', FANTOME: '« Je l’entends, la nuit. Pas M. Stanley. Un sifflet. Comme une locomotive, très loin. »' },
        relances: [{ q: '« Vous croyez aux esprits, vous, mon petit ? »', oui: '« Ah, je savais qu’on s’entendrait. Venez donc jeudi chez Mrs Pembroke. »', non: '« Vous y viendrez. On y vient tous, à un moment. »' }, { q: '« Vous voulez une tasse de thé ? »', oui: 'Elle verse un thé noir comme de la suie. « Avec du lait, bien sûr. On n’est pas des sauvages. »', non: '« Tant pis. Il est frais d’hier, pourtant. »' }] },

      sergent: { groupe: 'police', reg: 'populaire', tics: ['Bon,', 'Voyez-vous,'],
        dada: ['Mes roses, cette année, ont gelé. Toutes. Même les Gloire de Dijon.', 'Je fais ma tournée à bicyclette. Avec ce brouillard, je suis rentré deux fois dans le même réverbère.'],
        moi: { nom: '« Sergent Hobbs, du poste de Stoke Newington. »', age: '« Cinquante-cinq ans. La retraite dans deux ans, si Dieu veut. »', origine: '« Du Kent. Un village de houblon. Je regrette tous les jours. »', famille: '« Une femme, deux fils. L’un est dans la police, l’autre dans les assurances. Je préfère le premier. »', metier: '« Je surveille un quartier où il ne se passe rien. Enfin, où il ne se passait rien. »', loisirs: '« Les roses. Je les présente au concours de Clissold Park. Deuxième prix en dix-neuf. »', peur: '« De l’affaire Stanley. Trente ans de métier, et c’est la première que je ne comprends pas. »', croit: '« Je crois en Dieu et au règlement. Dans cet ordre, le dimanche. »', humeur: '« J’ai mal au dos. Le vélo. »', guerre: '« Trop vieux pour le front. J’ai gardé les prisonniers allemands à Alexandra Palace. De braves types, pour la plupart. »', defaut: ['« Je ne réponds pas à ça en service. »'] },
        sait: { STANLEY: '« Stanley ? Pas d’ennemis, pas de dettes, pas de femmes. Juste des trains. Et puis plus rien qu’une chambre pleine de fumée. »', ATKINS: '« Mrs Atkins ? Elle fait payer la visite. Je ferme les yeux. Elle n’a que ça pour vivre. »', BUTTER: '« Butter ? Le seul ami de Stanley. Un fou de trains, à Camberwell. »', FLEMING: '« Fleming, du Yard ? Je l’ai prévenu. Il a dit qu’il avait assez de Turcs comme ça. »', STOKE: '« Stoke Newington ? Des petits commerçants, des petits employés, des petites querelles. »', POLICE: '« Le métier ? Vous vous levez, vous enfilez la vareuse, et vous priez pour que rien n’arrive. »' } },

      butter: { groupe: 'savant', reg: 'savant', tics: ['Ah !', 'Figurez-vous que', 'Écoutez ça :'],
        dada: ['Savez-vous que l’écartement standard des voies, 4 pieds 8 pouces et demi, vient des chars romains ? On roule encore dans les ornières de César.', 'Le Flying Scotsman sortira cette année, dit-on. Une merveille. Je pleurerai.', 'Le bruit d’une locomotive dans la nuit, c’est la plus belle musique du monde. Après Elgar, peut-être.'],
        moi: { nom: '« Arthur Butter, président de l’Association des amateurs de trains de Londres. Président, trésorier, et membre le plus assidu. »', age: '« Cinquante-cinq ans. J’ai vu passer le dernier train à voie large du Great Western, en 1892. J’avais vingt-quatre ans, et j’ai pleuré. »', origine: '« Swindon ! La ville du chemin de fer. On naît avec de la vapeur dans les poumons. »', famille: '« Ma femme est partie en dix-huit. Pas morte : partie. Avec un marchand de charbon. Je ne lui en veux pas, j’ai toujours préféré les trains. »', metier: '« Quarante ans commis au Great Western. Les horaires, les correspondances. Je sais encore par cœur le Paddington-Penzance de 1910. »', loisirs: '« Mais les trains, voyons ! Les trains, les trains, et les trains. »', peur: '« Que ma cave soit inondée. Et… » Il baisse la voix. « De la maquette qu’on m’a confiée. Elle fait du bruit, la nuit. »', croit: '« Je crois à la ponctualité. C’est déjà une religion exigeante. »', humeur: '« Excellente ! J’ai un visiteur qui s’intéresse aux trains. »', guerre: '« J’organisais les trains de permissionnaires à Victoria. Ils partaient joyeux. Ils revenaient… autrement. »', boire: '« Un thé ! Je vous en sers un, avec un biscuit au gingembre. »', joueur: '« Vous m’êtes très sympathique. Vous aimez les trains, n’est-ce pas ? Tout le monde aime les trains, au fond. »', defaut: ['« Oh, parlons plutôt de trains, voulez-vous ? »'] },
        sait: { STANLEY: '« Henry ? Mon meilleur élève. Il a un œil pour les boggies que je n’ai jamais vu chez personne. Il est… parti, m’a-t-on dit. Je ne le crois pas. Les passionnés ne partent pas. »', TRAIN: '« Ah, les trains ! Que voulez-vous savoir ? Les locomotives Pacific ? Les voitures-lits de la Compagnie internationale ? Demandez, demandez ! »', VICTORIA: '« Victoria ! La gare des départs vers le Continent. Le quai huit, le train du ferry, et au bout, l’Orient-Express. Je n’y suis jamais monté. Je n’ai jamais eu les moyens. »', ATKINS: '« Mrs Atkins ? Une brave femme qui fait des affaires avec le malheur des autres. Comme beaucoup. »', ALEXIS: '« L’express de Liverpool, 1897… Les amateurs en parlent à voix basse. La moitié du train n’a jamais été retrouvée. Une moitié de train, vous imaginez ? »', CAMBERWELL: '« Camberwell ? Mon petit royaume. Le métro passe sous la maison, on l’entend ronronner. C’est pour ça que je l’ai achetée. »', FANTOME: '« Les trains fantômes ? Les cheminots en parlent tous, après la troisième pinte. Moi, je n’y crois pas. Enfin… je n’y croyais pas. »', POLICE: '« La police ? Ils ne connaissent rien aux trains. Rien du tout. »' },
        avis: { train: '« L’Orient-Express ? La plus belle ligne du monde. Je connais par cœur l’horaire de Calais à Constantinople, sans y être jamais monté. »', guerre: '« Les trains de permissionnaires. Je les ai tous vus partir, en quatorze. Je préfère parler des locomotives. »' },
        relances: [{ q: '« Vous savez ce qu’est une Pacific 4-6-2, {m} ? »', oui: '« Merveilleux ! Enfin quelqu’un ! Asseyez-vous, nous avons à parler. »', non: '« Quatre roues porteuses devant, six motrices, deux derrière. La perfection mécanique. Retenez-le, ça vous servira. »' }, { q: '« Vous prendrez bien un biscuit au gingembre ? »', oui: 'Il vous en tend trois. « Prenez, prenez. Ma femme les faisait mieux, mais elle est partie. »', non: '« Tant pis pour vous. »' }] },

      alexis: { groupe: 'occultiste', reg: 'fievreux', tics: ['Écoutez…', 'Chut.'],
        dada: ['Le train ne s’arrête pas. Il ralentit, parfois, pour respirer.', 'Mon fils est dans la voiture de queue. Il ne veut pas me voir.'],
        moi: { nom: '« Randolph Alexis. Je l’étais. Je crois que je le suis encore, par endroits. »', age: '« J’avais cinquante-six ans en 1897. Le train n’a pas d’âge. »', origine: '« Hampstead. Une maison avec une bibliothèque de quatre mille volumes. Ils doivent tous être en poussière. »', famille: '« Mon fils, Albert. Il a voulu me rejoindre. Il a réussi. »', metier: '« J’étudiais les choses qui ne veulent pas être étudiées. Elles m’ont étudié en retour. »', peur: '« De la gare d’arrivée. Il n’y en a pas. »', croit: '« Je ne crois plus. Je sais. C’est pire. »', humeur: 'Un rire qui finit en toux. « Excellent. Éternel. »', defaut: ['« Les questions sont des wagons. On les attelle, on les détache. »'] },
        sait: { TRAIN: '« Ce train ? Je l’ai appelé, en 1897. Il est venu. Il ne repart jamais à vide. »', STANLEY: '« Le jeune homme ? Il a trop aimé les trains. Le train l’a aimé en retour. »', FILS: '« Albert… Il a ouvert mes carnets. Je les avais pourtant fermés à clé. »', COEUR: '« Le cœur de la machine bat sous le plancher. Vous ne l’entendez pas ? »', RETOUR: '« Il y a un chemin de retour. Il passe par le cœur. »' } },

      stanley: { groupe: 'peuple', reg: 'fievreux', tics: ['Je…', 'Pardon…'],
        dada: ['J’ai froid. Il fait toujours froid entre deux gares.', 'Mrs Atkins doit s’inquiéter pour le loyer.'],
        moi: { nom: '« Henry Stanley. Employé aux écritures, chez Pickford’s. Enfin, j’étais. »', age: '« Quarante et un ans. Je crois. Ici, on perd le compte. »', origine: '« Stoke Newington. Chez Mrs Atkins. Il y a mes gravures, sur les murs. »', famille: '« Personne. Mes trains. Le club de M. Butter. »', metier: '« Je recopie des bordereaux de déménagement. Toute la journée. Des vies entières en colonnes. »', peur: '« De descendre. Et de rester. »', croit: '« Je voulais croire au train. Il existe. J’aurais préféré qu’il n’existe pas. »', humeur: '« Pas bien. Pas bien du tout. »', defaut: ['« Je ne sais pas. Je ne sais plus rien. »'] },
        sait: { BUTTER: '« M. Butter… Il faut lui dire de détruire la maquette. Il faut lui dire. »', ATKINS: '« Mrs Atkins. Elle faisait du thé trop fort. Je donnerais tout pour une tasse. »', MAQUETTE: '« Je l’ai achetée une livre. Une livre ! Pour la plus belle pièce que j’aie jamais vue. Elle m’a acheté, en vérité. »', TRAIN: '« Il m’a appelé par mon nom, la première nuit. Le sifflet a dit « Henry ». »' } },

      bibliothecaire: { groupe: 'savant', reg: 'formel', mefiant: 0.5, tics: ['Chut.', 'Je vous prierai de baisser la voix :'],
        dada: ['Le règlement de la salle de lecture tient en quarante-trois articles. Je les connais tous. Je les applique tous.', 'Karl Marx s’asseyait au rang L. Il laissait des miettes. Nous ne l’avons pas oublié.'],
        moi: { nom: '« Je suis le conservateur adjoint de la salle de lecture. Mon nom ne figure pas au catalogue. »', age: '« Assez âgé pour avoir connu le catalogue manuscrit. »', origine: '« Cambridge. Puis ici. Il n’y a rien eu entre les deux. »', famille: '« Je suis marié à la Bibliothèque, comme d’autres à l’Église. »', metier: '« Je garde le silence. Et les livres. Dans cet ordre. »', loisirs: '« Le latin. Je traduis Lucrèce, pour le plaisir. Le plaisir est rare. »', peur: '« Le feu. L’humidité. Et les lecteurs qui cornent les pages. »', croit: '« Je crois aux index. »', humeur: '« Convenable. »', defaut: ['« Ce n’est pas une question de bibliothèque. »'] },
        sait: { MUSEE: '« Le British Museum possède la plus grande bibliothèque du monde. Et des choses dans ses réserves qu’il vaudrait mieux ne pas cataloguer. »', SMITH: '« Le professeur Smith ? Lecteur assidu, place K 14. Il rendait ses volumes à l’heure. »', OCCULTE: '« Les ouvrages d’occultisme sont en Enfer. C’est le nom de la réserve, je vous assure. On n’y accède que sur autorisation. »', ARCHIVES: '« Les journaux sont à Colindale. Ou dans les morgues des quotidiens, à Fleet Street. Pas ici. »' } },

      concierge: { groupe: 'hotel', reg: 'formel', soi: ['CONCIERGE', 'PRATT'], tics: ['Si je puis me permettre,', 'Naturellement,', 'Ah,'],
        dada: ['Un client du deuxième a demandé un bain à trois heures du matin. Nous l’avons servi. C’est cela, un grand hôtel.', 'Le Savoy a l’électricité dans les ascenseurs. Nous avons Charles, qui tire la corde. Charles ne tombe jamais en panne.'],
        moi: { nom: '« Pratt, {m}. Cuthbert Pratt. Mais Pratt suffit amplement. »', age: '« L’âge d’un concierge est celui de son hôtel, {m}. Nous avons ouvert en 1898. »', origine: '« De Bath. Ma mère était gouvernante chez un évêque. J’ai été élevé dans le culte de la porcelaine. »', famille: '« Je suis célibataire, {m}. L’hôtel est une famille suffisamment nombreuse. »', metier: '« Concierge. C’est-à-dire tout savoir et ne rien dire. Sauf aux clients généreux. »', loisirs: '« La philatélie. J’ai un Penny Black. Je ne le montre qu’aux clients de longue durée. »', peur: '« Du scandale, {m}. Un hôtel survit à un incendie. Pas à un scandale. »', croit: '« Je crois à la discrétion. C’est presque une religion, dans la profession. »', humeur: '« Toujours au mieux devant les clients, {m}. »', guerre: '« Intendant au quartier général de Boulogne. J’y ai appris à trouver du champagne sous les bombes. »', boire: '« Pas pendant le service, {m}. Mais le bar ferme à onze heures, si vous voulez un conseil. »', argent: '« Les pourboires font vivre un concierge, {m}. Les mauvais clients le font mourir. »', secret: '« Tous les secrets de l’hôtel dorment dans cette tête, {m}. Ils y mourront. Sauf circonstance exceptionnelle. »', joueur: '« Vous êtes un client parfait, {m}. Pour l’instant. »', defaut: ['« Je crains que ce ne soit pas de mon ressort, {m}. »'] },
        sait: { MOUSTACHU: '« Un monsieur brun, à moustache, {m} ? Ça ne me dit rien. Mais je garderai l’œil ouvert, et je vous le dirai. »', HOTEL: '« Le Grand Hôtel de Russell Square, {m}. Soixante chambres, un ascenseur, et l’eau chaude à tous les étages. Presque tous. »', MUSEE: '« Le British Museum est à cinq minutes à pied. Je vous déconseille le soir : on s’y perd. »', VICTORIA: '« La gare Victoria, {m} ? Un taxi, vingt minutes. Trente avec le brouillard. Le train du ferry part à onze heures. »', SMITH: function (api) { return brule(api) ? '« Le professeur Smith ? Quelle tragédie, sa maison. Les journaux disent qu’on le cherche. »' : '« Le professeur Smith ? Il a pris le thé ici une fois. Il a démasqué la voyante de Lady Ashworth, vous vous rappelez ? »'; }, POLICE: '« La police, {m} ? Nous préférons qu’elle passe par l’entrée de service. »', TAXI: '« Un taxi ? Charles le siffle en deux minutes. Même par ce temps. »', CHAMBRE: '« Votre chambre, {m} ? Le troisième, sur cour. Douze shillings la nuit, petit déjeuner compris. Le radiateur est un caractère, mais il chauffe. »', ARGENT: '« Les règlements se font à la caisse, {m}. Le change aussi. »', TELEGRAMME: '« Les télégrammes ? Je m’en charge, {m}. Dites-moi seulement le destinataire. »' },
        relances: [{ q: '« Votre chambre vous convient-elle, {m} ? »', oui: '« J’en suis ravi. Le radiateur cogne, je le sais. Nous y travaillons depuis 1912. »', non: '« J’en suis désolé. Je fais monter une couverture supplémentaire. »' }] },

      agentsj: { groupe: 'police', reg: 'populaire', tics: ['Ben,', 'M’enfin,'],
        dada: ['Ma mère m’a tricoté des chaussettes. Elles sont trempées depuis six heures.', 'On m’a dit de rester là jusqu’à la relève. La relève, elle s’est perdue dans le brouillard.'],
        moi: { nom: '« Agent Purvis, matricule 4417. »', age: '« Vingt-trois ans, {m}. »', origine: '« De Kilburn. C’est à côté. Je suis rentré déjeuner chez ma mère. »', famille: '« Ma mère, mes trois sœurs. Je suis l’homme de la maison. »', metier: '« Ça fait huit mois. Avant, j’étais livreur chez Harrods. On m’a dit que la police, c’était l’avenir. »', loisirs: '« Le football, le samedi. Je joue arrière, pour l’équipe de la division. »', peur: '« De rester seul ici cette nuit, si vous voulez savoir. Avec les ruines qui craquent. »', croit: '« Je vais à l’église avec ma mère. »', humeur: '« Gelé, {m}. Complètement gelé. »', guerre: '« J’avais dix-huit ans à l’armistice. J’ai raté la guerre d’une semaine. Ma mère dit que c’est un miracle. »', defaut: ['« Je peux pas dire ça, {m}. Le règlement. »'] },
        sait: { RIGBY: '« Le sergent Rigby ? Il est passé ce matin. Il a reniflé les cendres et il a dit « essence ». »', SMITH: '« Le propriétaire ? On le cherche. Le domestique aussi. »', STJOHN: '« Le quartier ? Que des messieurs. Même les chiens ont l’air riches. »', TEMOIN: '« Le laitier ? Il parle à tout le monde. Il a même parlé au chien du voisin. »', POLICE: '« La police, c’est bien. On a une pèlerine. »' } },

      laitier: { groupe: 'peuple', reg: 'populaire', tics: ['Ben,', 'Moi, j’dis,'],
        dada: ['Ma jument, Betsy, elle connaît la tournée mieux que moi. Elle s’arrête toute seule devant chaque porte.', 'Le lait gèle dans les bouteilles, ce mois-ci. Ça fait sauter les bouchons.'],
        moi: { nom: '« Tom. Tom Haskins. Le laitier de la United Dairies. »', age: '« Quarante ans, à peu près. On a jamais été très sûrs, à la maison. »', origine: '« De Kentish Town. Ma mère trayait déjà, pour une laiterie de Camden. »', famille: '« Une femme, cinq gosses. Six avec la jument. »', metier: '« Je livre le lait depuis l’âge de douze ans. Je connais toutes les portes de St John’s Wood. Et ce qui se passe derrière. »', loisirs: '« Le pub, le samedi. Et les pigeons. »', peur: '« De ce que j’ai vu l’autre nuit. Je dors plus pareil. »', croit: '« Je crois que j’ai vu ce que j’ai vu. »', humeur: '« Pas mal, pas mal. Je dors mal, c’est tout. »', guerre: '« Conducteur d’attelage, à Salonique. Des mules. Plus têtues que Betsy. »', defaut: ['« Ça, j’sais pas. »'] },
        sait: { SMITH: '« Le professeur ? Il me laissait toujours une pièce à Noël. Un brave homme. Il prenait trois pintes par jour. »', BEDDOWS: '« M. Beddows ? Il comptait les bouteilles. Il vous rendait la monnaie au farthing près. »', STJOHN: '« Le quartier ? Des gens riches qui se lèvent tard. Moi je me lève à quatre heures. »', POLICE: '« L’agent ? Un gamin. Il a froid. Je lui ai donné du lait chaud. »' } },

      pike: { groupe: 'presse', reg: 'sec', mefiant: 0.5, tics: ['Bon.', 'Soit.'],
        dada: ['Mon système de fiches est le meilleur de Fleet Street. Le Times me l’a envié. Le Times peut toujours envier.', 'J’ai classé le jubilé de diamant de la vieille reine en trois jours. Trois jours, seule.'],
        moi: { nom: '« Mrs Pike. C’est assez. »', age: '« J’ai commencé ici l’année du jubilé de diamant. Calculez. »', origine: '« De Clapham. Mon père était typographe ici même. »', famille: '« Mr Pike est mort en 1908. Il ne rangeait jamais rien. »', metier: '« Archiviste. Je sais où se trouve chaque fait divers depuis 1897. Je ne sais pas où j’ai mis mes lunettes. »', loisirs: '« Le classement. Ne riez pas. »', peur: '« L’incendie. Un mégot de typographe, et c’est vingt-cinq ans de mémoire qui part en fumée. »', croit: '« Je crois aux faits. Je les range par ordre chronologique. »', humeur: '« Occupée. »', defaut: ['« Ce n’est pas classé. Donc ça n’existe pas. »'] },
        sait: { ARCHIVES: '« La morgue du Daily Courier : quarante mille volumes reliés. Rien ne se perd, sauf la patience. »', JOURNAL: '« Le Daily Courier ? Un bon journal. Mal écrit, bien archivé. »', SMITH: '« Smith ? Dossier S-214. Gros comme un annuaire. Il démasquait un médium par mois. »', ALEXIS: '« Alexis, 1897. Le déraillement de Liverpool. Volume 312. Personne ne l’a demandé depuis vingt ans, et vous êtes le deuxième ce mois-ci. »' } }
    };
    // ce que tout Londres sait, selon les jours et selon le milieu
    L.rumeurs = {
      SMITH: function (api, f) { return { h: '« Le professeur Smith ? Le chasseur de médiums. Un homme brillant, et un peu théâtral. »', p: '« Le professeur des fantômes ? Celui des journaux ? »', o: '« Smith ? Il nous a rendu service, autrefois. »' }[cls(f)] || null; },
      MEURTRES: function (api, f) { if (day(api) < 3) return null; return { h: '« Ces trois Turcs du Chelsea Arms… Une horreur. On dit qu’ils portaient tous le même nom. »', p: '« Les trois Turcs de Chelsea ? On dit qu’ils avaient le même nom, tous les trois. Ça porte malheur, un nom pareil. »', o: '« Chelsea ? C’est l’affaire de Fleming, au Yard. »' }[cls(f)]; },
      INCENDIE: function (api, f) { if (!brule(api)) return null; return { h: '« La maison du professeur Smith, à St John’s Wood. Réduite en cendres. On ne sait même pas s’il est vivant. »', p: '« La maison du savant qui a brûlé ? J’ai lu ça. Le domestique a filé, qu’ils disent. »', o: '« L’incendie de St John’s Wood ? C’est Rigby, aux incendies. »' }[cls(f)]; },
      STANLEY: function (api, f) { if (day(api) < 4) return null; return { h: '« Cet homme parti en fumée à Stoke Newington ? Une combustion spontanée, disent les journaux. Absurde. »', p: '« Le type de Stoke Newington qui a disparu dans la fumée ? Ma femme en fait des cauchemars. »', o: '« Stoke Newington ? Pas mon secteur. Une drôle d’histoire, paraît-il. »' }[cls(f)]; },
      TURCS: function (api, f) { return day(api) >= 3 ? '« Les Turcs ? Depuis Chelsea, on ne parle que d’eux. »' : '« Les Turcs ? On s’est battus contre eux, pendant la guerre. Maintenant on négocie, à Lausanne. »'; },
      CONFERENCE: function (api, f) { return day(api) >= 1 ? { h: '« La conférence de Smith ? J’ai lu le compte rendu. Le sceptique devenu prophète. Quel retournement. »', p: '« La conférence ? Paraît que le professeur a dit que les fantômes reviennent. Moi, je l’ai toujours su. »', o: '« La conférence de l’Institut ? Ce n’est pas mon rayon. »' }[cls(f)] : null; },
      MUSEE: function (api, f) { return '« Le British Museum ? Tout le monde connaît. Des momies, des statues, et une bibliothèque où il faut chuchoter. »'; },
      VICTORIA: function (api, f) { return '« Victoria ? La gare des trains pour le Continent. Douvres, le ferry, Paris. »'; },
      YARD: function (api, f) { return { h: '« Scotland Yard ? Sur l’Embankment, au bord de la Tamise. »', p: '« Le Yard ? J’y mets pas les pieds si je peux éviter. »', o: '« Le Yard, c’est la maison. »' }[cls(f)]; },
      POLICE: function (api, f) { return { h: '« La police métropolitaine fait de son mieux. Ce n’est pas toujours suffisant. »', p: '« Les bobbies ? Des braves types. Tant qu’on a rien à se reprocher. »', o: null }[cls(f)]; },
      CHELSEA: function (api, f) { return '« Chelsea ? Des artistes, des vieilles dames, des pensions. Et maintenant, des meurtres. »'; },
      ISLINGTON: function (api, f) { return '« Islington ? Au nord. Des marchés, des antiquaires, des gens pas toujours nets. »'; },
      STOKE: function (api, f) { return '« Stoke Newington ? Loin au nord. Des petites maisons toutes pareilles. Rien n’y arrive jamais. »'; },
      CAMBERWELL: function (api, f) { return '« Camberwell ? De l’autre côté du fleuve. Des employés, des rues tranquilles. »'; },
      CHEAPSIDE: function (api, f) { return '« Cheapside ? Dans la City. Des marchands le jour, des rats la nuit. »'; },
      STJOHN: function (api, f) { return brule(api) ? '« St John’s Wood ? Là où la maison du savant a brûlé. »' : '« St John’s Wood ? Des villas, des jardins, des gens qui ont des domestiques. »'; },
      ARCHIVES: function (api, f) { return '« Fleet Street ? La rue des journaux. Les rotatives tournent toute la nuit. »'; },
      AMBASSADE: function (api, f) { return '« L’ambassade turque ? À Belgravia. Ils ne sont même pas sûrs d’être une ambassade, en ce moment. »'; },
      INSTITUT: function (api, f) { return '« L’Institut impérial ? À South Kensington. De belles soirées pour de beaux messieurs. »'; },
      HOTEL: function (api, f) { return '« Votre hôtel ? À Bloomsbury ? Un quartier d’étudiants et de poètes. »'; },
      TRAIN: function (api, f) { return { h: '« Les trains ? La grande affaire du siècle passé. »', p: '« Les trains ? Je prends le métro, ça me suffit. »', o: '« Les trains ? Les gares sont pleines de pickpockets. »' }[cls(f)]; },
      FANTOME: function (api, f) { return { h: '« Les fantômes ? Une superstition qu’on croyait morte avec la reine Victoria. La guerre l’a ressuscitée. »', p: '« Les fantômes ? Y en a dans toutes les vieilles maisons de Londres. Faut pas les déranger, c’est tout. »', o: '« Les fantômes ne commettent pas de crimes. Les gens, si. »' }[cls(f)]; },
      OCCULTE: function (api, f) { return { h: '« L’occultisme est à la mode. Les salons de Mayfair en raffolent. »', p: '« Ces choses-là, faut pas y toucher. »', o: '« L’occultisme ? Une couverture pour l’escroquerie. »' }[cls(f)]; },
      GUERRE: function (api, f) { return null; }
    };
    L.converse = G.RPG.Parole.make(L);

    // ---------------------------------------------------------------- l'humeur : ce qui arrive quand on pousse les gens à bout
    function nomBas(id) { var n = (L.npcs[id] || {}).name || 'quelqu’un'; return /^(Le|La|Les|L’)\b/.test(n) ? n.charAt(0).toLowerCase() + n.slice(1) : n; }
    L.humeur = {
      cd: { bz: 120, ins: 360 },
      // un personnage faible, ou outragé, porte plainte : la police finit par vous trouver
      plainte: function (api, id) {
        var p = api.flag('plainte') || { n: 0 };
        p.n++; p.qui = id; p.depuis = api.s.min; p.traitee = false;
        api.flag('plainte', p);
      },
      // l'outrage à agent : une nuit au poste ; à la troisième arrestation, le juge
      arreter: function (api, id) {
        var n = (api.flag('arrestations') || 0) + 1, D = 1440;
        api.flag('arrestations', n);
        api.endTalk(false);
        if (n >= 3) { api.say('Le juge de Bow Street vous reconnaît. Il ne sourit pas.'); api.flag('fin', 'prison'); api.flag('combat', null); api.end(); return; }
        api.say(n === 1
          ? 'Outrage à agent. La nuit au poste de Bow Street, sur un banc de bois, entre un pickpocket et un marin qui chante. Au matin, on vous rend votre chapeau et vos lacets.'
          : 'Outrage à agent, encore. Cette fois, on prend votre nom, vos empreintes et deux nuits de votre temps. Le juge vous inflige cinq livres d’amende.');
        api.s.min = (Math.floor(api.s.min / D) + n) * D + 9 * 60; api.s.tick = 0;
        if (n > 1) api.pay(Math.min(5, api.s.money));
        api.go('yard');
        if (!api.flag('mort:fleming')) api.npc('fleming', id === 'fleming'
          ? '« Vous avez eu la nuit pour réfléchir. » Fleming ne lève pas les yeux de son dossier. « Je ne retiens rien contre vous. Cette fois. »'
          : '« On m’a raconté votre soirée. » Fleming referme un dossier. « Insulter mes hommes ne vous avancera à rien. Une fois, je veux bien. Pas deux. »');
        api.lose(1);
      }
    };
    var evPlainte = L.everyTurn;
    L.everyTurn = function (api, fired) {
      var p = api.flag('plainte');
      if (p && !p.traitee && !api.s.ended && !api.s.talk && !api.flag('combat') && api.s.min - p.depuis >= 90 && !(L._c && L._c.special && L._c.special(api))) {
        p.traitee = true; api.flag('plainte', p);
        var par = nomBas(p.qui);
        if (p.n === 1) api.event((api.s.loc === 'hotel' ? 'Dans le hall, un agent en pèlerine vous attend, carnet à la main. ' : 'Un agent en pèlerine vous aborde, carnet à la main. ') + '« Une plainte contre vous, déposée par ' + par + '. Insultes, esclandre. » Il note votre nom, lentement. « Rien de bien grave. Mais je vous ai à l’œil, {m}. »');
        else if (p.n === 2) { api.event('Le même agent, ou son frère. « Deuxième plainte, {m}. Par ' + par + ', cette fois. » Il vous tend un papier. « Deux livres d’amende, payables tout de suite. La prochaine fois, ce sera le poste. »'); api.pay(Math.min(2, api.s.money)); }
        else { api.event('Deux agents vous attendent, l’un devant vous, l’autre derrière. « Encore une plainte. ' + cap0(par) + '. Vous allez nous suivre. »'); L.humeur.arreter(api, null); }
        return true;
      }
      return evPlainte(api, fired);
    };
    function cap0(x) { return x.charAt(0).toUpperCase() + x.slice(1); }
  }

  // ================================================================ le prologue, à bord du Simplon-Orient-Express
  if (PR) {
    PR.fiches = {
      serveur: { groupe: 'domestique', reg: 'domestique', fr: true, tics: ['Monsieur,', 'Si monsieur permet,'],
        dada: ['Monsieur sait que la Compagnie interdit de servir après minuit. Mais pour monsieur…', 'Le chef a encore brûlé la sole. Que monsieur ne commande pas la sole.'],
        moi: { nom: '« Bastien, monsieur. C’est écrit sur la plaque. »', age: '« Trente-neuf ans, monsieur. Dont seize sur les rails. »', origine: '« De Dijon, monsieur. Mon père était cheminot au dépôt. »', famille: '« Une femme à Dijon, monsieur. Je la vois trois jours par mois. C’est sans doute pour ça que nous sommes heureux. »', metier: '« Serveur à la Compagnie internationale des wagons-lits, monsieur. Seize ans. J’ai servi un grand-duc, deux ministres et un assassin. On ne sait jamais lequel est lequel avant le dessert. »', loisirs: '« Monsieur me demande mes loisirs ? Je dors, monsieur. Quand la ligne le permet. »', peur: '« Des tunnels, monsieur. Le Simplon fait vingt kilomètres. Vingt kilomètres sans ciel. »', croit: '« Je suis catholique, monsieur, comme tout le monde. Mais sur cette ligne, on finit par croire à autre chose. »', humeur: '« Monsieur est bien aimable. La nuit est longue. »', guerre: '« Brancardier, monsieur. Verdun. Monsieur me permettra de ne pas en dire davantage. »', boire: '« Un cognac, monsieur ? Sans eau, je conseillerais. Ce soir, je conseillerais sans eau. »', argent: '« Les pourboires, monsieur. La Compagnie paie mal, les voyageurs paient mieux. »', secret: '« Un serveur entend tout, monsieur. Et il oublie tout en descendant à Lausanne. »', joueur: '« Monsieur est un client courtois. C’est plus rare qu’on ne pense. »', defaut: ['« Monsieur me pose une question que je ne sais pas comment prendre. »'] },
        sait: { VEUVE: '« Madame Vasseur ? Elle prend ce train chaque mois, monsieur. Elle va sur la tombe de son mari, à Lausanne. Elle fait des réussites. Elle ne gagne jamais. »', CONDUCTEUR: '« Paolo ? Le conducteur des voitures-lits. Un Italien, monsieur. Il parle trop, mais il connaît la ligne mieux que le mécanicien. »', TRAIN: '« Le Simplon-Orient-Express, monsieur. Paris, Lausanne, Milan, Venise, Trieste, Belgrade, Constantinople. Je descends à Lausanne. Toujours. »', CUISINE: '« La cuisine ? Un réduit de deux mètres, monsieur, où l’on fait des miracles et des sauces trop salées. »', RESTAURANT: '« Le wagon-restaurant, monsieur. Marqueterie Lalique, cuivres, nappes brodées. On croirait Maxim’s, si Maxim’s tanguait. »', LAMPE: '« Les lampes, monsieur ? Elles vacillent depuis Dijon. L’électricien de la Compagnie dit que tout va bien. »' },
        relances: [{ q: '« Monsieur voyage jusqu’où, si ce n’est pas indiscret ? »', oui: '« Bien, monsieur. »', non: '« Comme monsieur voudra. »', autre: '« Belle destination, monsieur. »' }, { q: '« Monsieur souhaite-t-il un autre cognac ? »', oui: 'Il verse. Un doigt, puis deux. « La maison offre le second. »', non: '« Bien, monsieur. »' }] },
      veuve: { groupe: 'mondain', reg: 'mondain', fr: true, tics: ['Mon pauvre ami,', 'Voyez-vous,', 'Ah,'],
        dada: ['Le valet de pique ne sort jamais. Jamais. C’est une réussite qui ne réussit pas.', 'Mon mari disait que les trains de nuit étaient faits pour les confidences. Il en faisait beaucoup. Pas à moi.'],
        moi: { nom: '« Irène Vasseur. Madame veuve Vasseur, pour les contrôleurs. »', age: '« On ne demande pas l’âge d’une dame, voyons. Disons que j’ai dansé à l’Exposition de 1889. »', origine: '« De Lyon. Une famille de soyeux. Nous avons fait fortune dans les rubans, puis nous l’avons défaite dans les chevaux. »', famille: '« Mon mari, Edmond, est enterré à Lausanne. Il voulait voir le lac pour l’éternité. Je lui rends visite chaque mois. Il ne me reçoit jamais mal. »', metier: '« Je suis veuve, mon ami. C’est un métier à plein temps. »', loisirs: '« Les réussites. Le piquet, quand je trouve un partenaire qui ne triche pas. Je n’en trouve jamais. »', peur: '« De mourir dans un train. Ce serait d’un commun. »', croit: '« Je crois en Dieu le dimanche et aux cartes le reste de la semaine. »', humeur: '« Je m’ennuie, mon ami. C’est mon état naturel. »', guerre: '« Mon neveu est mort au Chemin des Dames. Il avait les yeux de ma sœur. »', boire: '« Une tisane. Le cognac, c’est pour les hommes et pour les veuves heureuses. »', secret: '« J’en ai tant, mon ami. Je les range avec les cartes. »', joueur: '« Vous êtes charmant. Un peu trop curieux. Mais charmant. »', defaut: ['« Voilà une question bien indiscrète, mon ami. »'] },
        sait: { SERVEUR: '« Bastien ? Il me sert ma tisane depuis cinq ans. Il me ment sur l’heure qu’il est. C’est délicat de sa part. »', CONDUCTEUR: '« Paolo ? Un bavard. Il parle de Mussolini comme d’un saint. Je le laisse dire. »', CARTES: '« Mes cartes ? Un jeu de 1880, qui a appartenu à ma mère. Il ne m’a jamais porté chance. Je le garde par fidélité. »', TRAIN: '« Ce train ? Je le prends depuis douze ans. Il a changé de nom trois fois. Pas de lenteur. »', LAC: '« Le lac Léman, mon ami. Edmond le regarde depuis le cimetière de Montoie. Il a une meilleure vue que moi. »' },
        relances: [{ q: '« Vous jouez au piquet, mon ami ? »', oui: '« Enfin ! Asseyez-vous. Je vous préviens : je triche. »', non: '« Dommage. Les hommes ne savent plus rien faire. »' }, { q: '« Vous êtes marié, jeune homme ? »', oui: '« Alors rentrez chez vous plutôt que de traîner dans les trains. »', non: '« Vous avez bien raison. Le mariage est un voyage de nuit : long, et on n’y dort pas. »' }] },
      conducteur: { groupe: 'cheminot', reg: 'populaire', fr: true, tics: ['Madonna,', 'Ecco,', 'Allora,'],
        dada: ['Au Simplon, monsieur, vingt kilomètres sous la montagne. On entend l’eau couler dans la roche. Comme des larmes.', 'Ma mamma, à Domodossola, elle allume un cierge chaque fois que je passe le tunnel.'],
        moi: { nom: '« Paolo Ferrante, monsieur. Conducteur de la voiture 7 et 8. »', age: '« Trente-deux ans, monsieur. »', origine: '« De Domodossola, juste après le tunnel. Je suis né à la sortie du Simplon. C’est un signe, non ? »', famille: '« Ma mamma, quatre sœurs, et une fiancée à Milan. Elle attend depuis cinq ans. Elle est patiente, Lucia. »', metier: '« Je fais les lits, je réveille les voyageurs, je tamponne les passeports aux frontières. Et je surveille, monsieur. Toujours je surveille. »', loisirs: '« Le football ! Pro Vercelli, monsieur. Champions d’Italie. Vous connaissez ? Non ? Personne connaît. »', peur: '« Du tunnel, la nuit. Et de la voiture 7, ce soir. »', croit: '« Je suis catholique, monsieur. Et je crois au mauvais œil. Les deux, c’est mieux. »', humeur: '« Bene, bene. Un peu fatigué. »', guerre: '« Alpini, sur le Piave. Le froid, monsieur. Le froid et les Autrichiens. »', boire: '« Un petit grappa, en cachette. La Compagnie ne doit pas savoir. »', defaut: ['« Ah, ça, monsieur, je sais pas. »'] },
        sait: { RAVEL: '« Monsieur Ravel ? Voiture 7, compartiment 7. Il ne sort jamais. Il commande de l’eau. Que de l’eau. Et il ne la boit pas. »', COMPARTIMENT: '« Les compartiments ? Je les connais tous. Le 7 sent l’étang, ce soir. Je comprends pas. »', SEPT: '« Le sept ? Madonna. Ne me parlez pas du sept. »', SERVEUR: '« Bastien ? Un brave. Il me garde du café chaud. »', VEUVE: '« La signora Vasseur ? Elle donne des pourboires énormes et elle dit jamais merci. Une vraie dame. »', TRAIN: '« Ce train, monsieur, c’est le plus beau du monde. Avant la guerre, c’était plus beau encore. »' },
        avis: { mussolini: '« Il Duce ? Il va remettre l’Italie debout, monsieur ! Les trains vont arriver à l’heure ! Bon, ils arrivaient déjà à l’heure, sur cette ligne. »', guerre: '« Le Piave, monsieur. On a tenu. Je parle pas du reste. »' },
        relances: [{ q: '« Vous avez entendu, vous aussi, le bruit d’eau, monsieur ? »', oui: 'Il se signe. « Alors je suis pas fou. Je suis pas fou. »', non: '« Tant mieux, monsieur. Tant mieux pour vous. »' }] }
    };
    PR.rumeurs = {};
    PR.converse = G.RPG.Parole.make(PR);
    // à bord, c'est le chef de train qu'on prévient
    PR.humeur = {
      cd: { bz: 15, ins: 30 },
      plainte: function (api, id) { var p = api.flag('plainte') || { n: 0 }; p.n++; p.qui = id; p.depuis = api.s.min; p.traitee = false; api.flag('plainte', p); }
    };
    var evPR = PR.everyTurn;
    PR.everyTurn = function (api, fired) {
      var p = api.flag('plainte');
      if (p && !p.traitee && !api.s.ended && !api.s.talk && api.s.min - p.depuis >= 3) {
        p.traitee = true; api.flag('plainte', p);
        api.event(p.n === 1
          ? 'Le chef de train vient vous trouver, sanglé dans son uniforme bleu nuit. « {M}, on me signale un voyageur qui importune le personnel. Je compte sur vous pour que ce soit la dernière fois. »'
          : 'Le chef de train, de nouveau, et cette fois il ne salue pas. « {M}, deuxième plainte. Au prochain incident, je vous fais descendre à Lausanne, avec vos bagages et sans vos excuses. »');
        return true;
      }
      return evPR ? evPR(api, fired) : false;
    };
  }
})(typeof window !== 'undefined' ? window : globalThis);
